<?php require_once __DIR__.'/professional_assets/bootstrap_portal.php'; require_role(['admin']);$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['worker_name']);$job=trim($_POST['job_title']);$login=trim($_POST['loginid']);$pass=password_hash($_POST['password'],PASSWORD_DEFAULT);$phone=trim($_POST['phone']);$salary=(float)$_POST['salary'];$q=$con->prepare('INSERT INTO workers(worker_name,job_title,loginid,password,phone,salary) VALUES(?,?,?,?,?,?)');$q->bind_param('sssssd',$name,$job,$login,$pass,$phone,$salary);$q->execute();log_action($con,'Worker Created',$login);$msg='Worker account created.';}$rows=$con->query('SELECT * FROM workers ORDER BY worker_id DESC');?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"><title>Workers</title></head><body class="module-body"><div class="module-wrap"><div class="module-head"><div><span class="eyebrow">STAFF</span><h1>Workers & Staff</h1><p>Receptionists, cleaners, accountants, security and other hospital workers.</p></div></div><?php if($msg):?><div class="success"><?php echo esc($msg);?></div><?php endif;?><div class="panel"><h2>Create worker account</h2><form method="post" class="form-grid"><label>Full name<input name="worker_name" required></label><label>Job title<input name="job_title" required value="Staff"></label><label>Username<input name="loginid" required></label><label>Password<input name="password" type="password" required></label><label>Phone<input name="phone"></label><label>Monthly salary<input name="salary" type="number" step="0.01" value="0"></label><button class="primary-btn">Create Worker</button></form></div><div class="panel"><h2>Worker accounts</h2><div class="table-scroll"><table><tr><th>Name</th><th>Job</th><th>Username</th><th>Salary</th><th>Status</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?php echo esc($r['worker_name']);?></td><td><?php echo esc($r['job_title']);?></td><td><?php echo esc($r['loginid']);?></td><td><?php echo esc(number_format((float)$r['salary'],2));?></td><td><?php echo esc($r['status']);?></td></tr><?php endwhile;?></table></div></div></div></body></html>